class RateLimiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.counts = {}

    def allow(self, client_id, current_time):
        window_start, count = self.counts.get(client_id, (current_time, 0))
        if current_time - window_start >= self.window:
            window_start, count = current_time, 0
        if count >= self.limit:
            self.counts[client_id] = (window_start, count)
            return False
        self.counts[client_id] = (window_start, count + 1)
        return True


ALLOWED_ORIGINS = {"https://app.example.com"}


def cors_headers(origin):
    if origin in ALLOWED_ORIGINS:
        return {"Access-Control-Allow-Origin": origin}
    return {}


limiter = RateLimiter(limit=2, window=10)

for t in [0, 1, 2, 12]:
    print(t, limiter.allow("client-a", t))

print(cors_headers("https://app.example.com"))
print(cors_headers("https://evil.example.com"))
